toolArgs.file_text:
namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications.AddRange(new[]
        {
            MakeNotification("Welcome to the app!"),
            MakeNotification("Your profile was updated."),
            MakeNotification("You have a new follower."),
        });
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving at random.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            if (Random.Shared.Next(0, 3) == 0)
            {
                var messages = new[]
                {
                    "New comment on your post.",
                    "Someone liked your photo.",
                    "Deployment succeeded.",
                    "Reminder: meeting in 10 minutes.",
                    "Your report is ready to download.",
                };
                _notifications.Add(
                    MakeNotification(messages[Random.Shared.Next(messages.Length)]));
            }
        }
    }

    private Notification MakeNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

